import mapUrl from "../../assets/maps/MountainTrack.glb?url";
import { loadMap, buildMapTrack } from "./glb-map.js";

// ---------------------------------------------------------------------
// OFFICIAL MAP 2 — Mountain Track
//
// A hill climb and descent round a mountain, modelled in Blender
// (assets/maps/MountainTrack.glb, generated by blender/mountain/
// mountain_track.py). 1.48 km, 12 m of road, climbing from 8 m to 83 m,
// through a closed tunnel at the summit and back down over a viaduct.
// Every corner is a left-hander and every one leans the right way: the
// outside edge is up, from about 2 degrees on the straights to 13 in the
// two tight corners (R19 after the start, R15 at 1.33 km). Nothing leans
// the wrong way.
//
// Unlike the other two maps this one has real barriers: continuous
// guardrails on both sides, 6.3 m from the centre and 0.15-0.8 m high,
// which collide as their own mesh — so no soft wall. The tunnel walls
// collide the same way. The terrain is scenery only: the rails keep
// every car on the road, and a 45 000-triangle mountain would be a lot
// of collision geometry for nobody to touch.
//
// The start line (road sample 0) sits on a flat straight with nothing
// tighter than R30 for 60 m either way, so the grid lines up on level
// ground and gets going before the first corner.
//
// Mesh names are as three.js sanitises them: spaces become underscores.
// ---------------------------------------------------------------------

buildMountain.preload = () => loadMap(mapUrl);

// `gltf` is what preload() resolved to — loadLevel in main.js awaits it.
export function buildMountain(RAPIER, world, scene, gltf) {
  const map = buildMapTrack(RAPIER, world, scene, gltf, {
    name: "MountainTrack",
    roadName: "Mountain_Race_Track",
    surfaces: [
      { match: /^Mountain_Race_Track$/, friction: 1.0 },
      // Asphalt between the road edge and the rails, on the same plane
      { match: /^Road_Shoulder_(Left|Right)$/, friction: 1.0 },
    ],
    walls: /^(Guardrail_(Left|Right)|Tunnel_Wall)$/,
    decals: /^(White_Edge|Yellow_Centre|Race_Direction_Arrow|Start_Finish_Checker|Red_White_Curb)/,
    minimap: /^(Mountain_Race_Track|White_Edge|Guardrail_(Left|Right)$)/,
    // The rails are the boundary, as on a generated track, and wallLimit
    // is where they stand. A soft wall here fought the rails: where the
    // centreline and the modelled road disagree by even half a metre, it
    // held cars short of a rail they could see and they stalled there.
    softWalls: false,
    wallLimit: 6.2,
    // Light smoothing only: the ribbon is evenly sampled (1.84 m) and
    // smooth, and the default (6 m, 3 passes) would pull the line off the
    // modelled road in the two tight corners.
    centreline: { spacing: 3, passes: 1 },
    track: { checkpointSpacing: 120 },
  });
  const { track } = map;

  const gate = track.spawnAt(0);
  return {
    // Falling rocks where there is a real slope above the road (measured:
    // the ground 25 m to one side is 25-50 m above it). Not in the tunnel
    // (683-821 m), not on the viaduct (1,018-1,160 m), not on the downhill
    // face (about 340-1,000 m, where the ground falls away), and clear of
    // the start line. The uphill side is found from the terrain.
    rockfall: {
      zones: [
        { s0: 190, s1: 290 },
        { s0: 1180, s1: 1290 },
        { s0: 1320, s1: 1420 },
      ],
      ground: map.group.children.filter((m) => /Grass|Mountain Rock|Rock Highlight/.test(m.name)),
      signOffset: 7.4, // just beyond the rail
    },
    // The viaduct (1,018-1,160 m) is the one stretch with nothing beside
    // the road at all — no slope to drop rocks, no rail-height drop-off,
    // just open air over the gorge. A crosswind belongs there and
    // nowhere else on this lap. 5200 N, not 4200: on a 1200 kg car that's
    // ~4.3 m/s^2 at full strength — comfortably below boostForce (6500 N)
    // but enough to actually need countersteer, not just a push too
    // gentle for the tyres' own grip to shrug off unnoticed.
    crosswind: [{ s0: 1018, s1: 1160, side: 1, force: 5200, signOffset: 7.4 }],
    // Low ground mist, not summit cloud, filling the whole gap between the
    // last rockfall zone and the line. That zone is the 1180-1290 one, not
    // the 1320-1420 entry above: Rockfall's own uphill-slope check
    // (measured from the terrain, not configured) finds no real slope
    // over that last stretch and drops it silently — so it never arms,
    // never signs, never drops a rock, and 1320-1420 is actually just more
    // plain road. The real gap to the line is 1290-1474.7, not 1420-1474.7.
    // A short 10 m ramp (see FogPatch's `ramp` option, default 40) so it
    // reads as present almost the instant the rocks stop, not a 40 m fade
    // that is still near-baseline visibility for the first several
    // seconds. Full strength holds for the next 160 m, nearly the whole
    // remaining stretch, clearing only in the last 15 m before the line —
    // there to be driven through right up to the flag, not resolved with
    // a big empty buffer beforehand, but still gone before the line
    // itself so it never reads as lingering past it. Denser than the
    // default near/far too (12/80, not 20/140): the default read as too
    // faint to notice at a glance.
    fogPatch: [{ s0: 1300, s1: 1460, ramp: 10, near: 12, far: 80, signOffset: 7.4 }],
    name: "mountain",
    index: 2,
    title: "Mountain Track",
    track,
    // Solo: the mountain is you against the road. Only the Grand Prix is
    // a race against other cars.
    opponents: 0,
    // One lap up, through the tunnel, and back down to the line before
    // the clock runs out. Boost orbs buy you more of it rather than
    // filling the boost meter — the climb is the opponent here.
    pickups: { repair: 4, boost: 5, boostSeconds: 10 },
    // 90 s: this 1.48 km lap climbs, threads a tunnel, a crosswind and a
    // fog patch right before the line, and descends again — needs ~59
    // km/h average, slower than the City by nature, but still tight
    // enough that actually handling the hazards (not just surviving
    // them) is what gets you home in time.
    race: { laps: 1, timeLimit: 90 },
    spawn: gate.position,
    quaternion: gate.quaternion,
    // Dusk on the pass. The sun is about 10 degrees above the horizon,
    // so it rakes across the slopes from the side: lit rock faces glow
    // orange, everything turned away from it falls into a cool blue fill,
    // and every tree and ridge throws a long shadow across the road. The
    // headlights come on from this level onward.
    //
    // Bloom's threshold is higher than the default here: a low sun lights
    // the side of the white car almost head-on, and at 1.6 the paint
    // itself bloomed.
    lit: {
      sun: [-120, 24, 45],
      sunColor: 0xff9a55,
      sunIntensity: 3.0,
      hemi: [0x5a78b8, 0x2b2a35, 1.0],
      // A big low sun, and dusky clouds lit orange on the side facing it.
      sky: { top: 0x1e3a78, horizon: 0xf09a58, bottom: 0x3a3640, clouds: 0.4, cloudColor: 0x7a5d6c, sunDisc: 10, sunSize: 0.045 },
      fog: [0x9a8590, 200, 900],
      exposure: 1.05,
      envIntensity: 0.35,
      bloom: { threshold: 2.6, strength: 0.4, radius: 0.35 },
      headlights: true,
      glow: 0xff9a3c, // the setting sun
    },
    dispose: map.dispose,
  };
}
